using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace DataQualityStudio
{
    /// <summary>
    /// XrmToolBox entry point (discovered through MEF).
    /// Icons: Resources/icon32.png (SmallImageBase64) and Resources/icon80.png (BigImageBase64).
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Data Quality Studio"),
     ExportMetadata("Description", "Dataverse Excel Mapping & Data Quality Studio: map Excel/CSV migration templates to Dataverse columns, validate required fields, data types, choices and lookups, preview transformed values and export row-level errors with suggested corrections. Mappings are saved as reusable profiles."),
     ExportMetadata("SmallImageBase64", ""),
     ExportMetadata("BigImageBase64", ""),
     ExportMetadata("BackgroundColor", "#E3F2EE"),
     ExportMetadata("PrimaryFontColor", "#0B5D57"),
     ExportMetadata("SecondaryFontColor", "#5E6B69")]
    public class DataQualityStudioPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new DataQualityStudioControl();
        }
    }
}
